public class ObjectReader__findRootDeserializer_TriageGen2Test {

    private ObjectMapper mapper;
    private DeserializationContext ctxt;
    private JavaType valueType;
    private JsonDeserializer<Object> mockDeserializer;

    // Accessor class to instantiate the protected ObjectReader via reflection or a subclass
    // since the constructor is protected and we need to manipulate internal state for coverage.
    private static class TestObjectReader extends ObjectReader {
        protected TestObjectReader(ObjectMapper mapper, DeserializationConfig config) {
            super(mapper, config);
        }

        public JsonDeserializer<Object> callFindRootDeserializer(DeserializationContext ctxt, JavaType valueType) 
                throws JsonMappingException {
            return _findRootDeserializer(ctxt, valueType);
        }

        // Helper to inject values into private fields for testing branch coverage
        public void setRootDeserializer(JsonDeserializer<Object> deser) throws Exception {
            Field field = ObjectReader.class.getDeclaredField("_rootDeserializer");
            field.setAccessible(true);
            field.set(this, deser);
        }

        public void setRootDeserializers(Map<JavaType, JsonDeserializer<Object>> map) throws Exception {
            Field field = ObjectReader.class.getDeclaredField("_rootDeserializers");
            field.setAccessible(true);
            field.set(this, map);
        }
    }

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        ctxt = mock(DeserializationContext.class);
        valueType = mapper.getTypeFactory().constructType(String.class);
        mockDeserializer = new StdDeserializer<Object>(String.class) {
            @Override
            public Object deserialize(com.fasterxml.jackson.core.JsonParser p, DeserializationContext ctxt) {
                return null;
            }
        };
    }

    @Test
    public void test_findRootDeserializer_returnsExistingRootDeserializer() throws Exception {
        TestObjectReader reader = new TestObjectReader(mapper, mapper.getDeserializationConfig());
        reader.setRootDeserializer(mockDeserializer);

        JsonDeserializer<Object> result = reader.callFindRootDeserializer(ctxt, valueType);

        assertEquals(mockDeserializer, result);
    }

    @Test(expected = JsonMappingException.class)
    public void test_findRootDeserializer_throwsExceptionWhenValueTypeIsNull() throws JsonMappingException {
        TestObjectReader reader = new TestObjectReader(mapper, mapper.getDeserializationConfig());
        reader.callFindRootDeserializer(ctxt, null);
    }

    @Test
    public void test_findRootDeserializer_returnsCachedDeserializerFromMap() throws Exception {
        TestObjectReader reader = new TestObjectReader(mapper, mapper.getDeserializationConfig());
        Map<JavaType, JsonDeserializer<Object>> cache = new HashMap<>();
        cache.put(valueType, mockDeserializer);
        reader.setRootDeserializers(cache);

        JsonDeserializer<Object> result = reader.callFindRootDeserializer(ctxt, valueType);

        assertEquals(mockDeserializer, result);
    }

    @Test
    public void test_findRootDeserializer_resolvesNewDeserializerAndCachesIt() throws JsonMappingException, Exception {
        TestObjectReader reader = new TestObjectReader(mapper, mapper.getDeserializationConfig());
        Map<JavaType, JsonDeserializer<Object>> cache = new HashMap<>();
        reader.setRootDeserializers(cache);

        when(ctxt.findRootValueDeserializer(valueType)).thenReturn(mockDeserializer);

        // First call: should resolve via context
        JsonDeserializer<Object> result1 = reader.callFindRootDeserializer(ctxt, valueType);
        assertEquals(mockDeserializer, result1);
        assertEquals(1, cache.size());
        assertEquals(mockDeserializer, cache.get(valueType));

        // Second call: should return from cache (verify context is not called again)
        JsonDeserializer<Object> result2 = reader.callFindRootDeserializer(ctxt, valueType);
        assertEquals(mockDeserializer, result2);
        Mockito.verify(ctxt, Mockito.times(1)).findRootValueDeserializer(valueType);
    }

    @Test(expected = JsonMappingException.class)
    public void test_findRootDeserializer_throwsExceptionWhenContextReturnsNull() throws JsonMappingException {
        TestObjectReader reader = new TestObjectReader(mapper, mapper.getDeserializationConfig());
        Map<JavaType, JsonDeserializer<Object>> cache = new HashMap<>();
        reader.setRootDeserializers(cache);

        when(ctxt.findRootValueDeserializer(valueType)).thenReturn(null);

        reader.callFindRootDeserializer(ctxt, valueType);
    }
}
